/* ===== 视频下载：走后台的 chrome.downloads =====
 * 页面里的 fetch 受 CORS 限制，而且原来写死了 credentials:"omit" 不带 cookie ——
 * 抖音 CDN 对部分视频（合集、需要登录的）会直接 403，表现就是"有些视频能下、有些不能"。
 * chrome.downloads 是浏览器级下载：不受 CORS 约束、自动带 cookie、
 * 并且能正确创建 "douyin/xxx.mp4" 这种子目录（<a download> 会把斜杠吃掉）。
 * 万一后台下不了（比如 blob: 地址是页面作用域的），再回落到内容脚本。 */
/* 后台兜底通道：部分抖音 CDN 不返回 Access-Control-Allow-Origin，
 * 页面主世界的 fetch 会被 CORS 拦掉（报 "Failed to fetch"）。
 * 后台 fetch 受 host_permissions 保护、不受 CORS 约束，
 * 但它默认不带 Referer —— 用 declarativeNetRequest 临时注入补齐
 * （DNR 的 modifyHeaders 对 xmlhttprequest 类型是有效的，
 *   这与它管不了 downloads.download 是两回事）。
 * 数据交给页面主世界存盘：service worker 里没有 URL.createObjectURL。 */
/* 第二通道：offscreen 文档。
 * 为什么需要它：部分抖音 CDN 不返回 Access-Control-Allow-Origin，页面 fetch 被 CORS 拦死；
 * 而 service worker 里又没有 URL.createObjectURL，没法把内存里的数据交给下载器。
 * offscreen 是扩展页面：它的 fetch 受 host_permissions 保护（不受 CORS），
 * 又有 DOM 能 createObjectURL，还能直接调 downloads.download（可保留 "子目录/文件名"）。
 * 关键：扩展环境下 Origin 会被浏览器强制写成 chrome-extension://<id> 且无法用 fetch 参数覆写，
 * 必须靠 declarativeNetRequest 改写 —— 而 DNR 规则要命中「扩展自己发起的请求」，
 * 必须写 initiatorDomains:[扩展ID]，否则规则不会生效。 */
/* ===== 修复补丁 v6：不依赖 API 签名的直链通道 ===== */

/* --- A. 媒体请求嗅探 ---
 * 播放抖音视频时必然会请求视频流。这里把真实请求过的直链缓存下来，
 * 用 storage.session 持久化（service worker 休眠后会重启，内存 Map 会丢）。 */
var _mediaCache=[];
var _mediaTimer=null;
function _mediaSave(){
  if(_mediaTimer)clearTimeout(_mediaTimer);
  _mediaTimer=setTimeout(function(){
    try{F.storage.session.set({_mediaUrls:_mediaCache.slice(-20)}).catch(function(){})}catch(_e){}
  },1200)
}
function _initMediaSniffer(){
  try{
    F.storage.session.get('_mediaUrls').then(function(s){
      if(s&&s._mediaUrls&&s._mediaUrls.length)_mediaCache=s._mediaUrls
    }).catch(function(){})
  }catch(_e){}
  try{
    F.webRequest.onBeforeRequest.addListener(function(ev){
      try{
        if(ev.initiator&&ev.initiator.indexOf("extension://")!==-1)return;
        const u=ev.url||"";
        if(!/^https?:/i.test(u))return;
        if(u.length<60)return;
        /* 排除分片/图片/样式，只留完整视频直链 */
        if(/\.(m3u8|ts|jpe?g|png|webp|gif|css|js|json|svg|woff2?)(\?|$)/i.test(u))return;
        const ok=/\.mp4(\?|$)/i.test(u)||/mime_type=video_mp4/i.test(u)||/douyinvod\.com/i.test(u)||/\/video\/tos\//i.test(u);
        if(!ok)return;
        if(_mediaCache.some(function(x){return x.url===u}))return;
        _mediaCache.push({url:u,ts:Date.now()});
        if(_mediaCache.length>20)_mediaCache.shift();
        _mediaSave()
      }catch(_e3){}
    },{
      urls:["https://*.douyinvod.com/*","https://*.douyin.com/*","https://*.bytecdnapi.com/*","https://*.douyincdn.com/*","https://*.ibytedtos.com/*","https://*.byteimg.com/*"],
      types:["media","xmlhttprequest","other","object"]
    })
  }catch(_e){}
}

/* --- B. 从播放页取直链（Resource Timing 优先，DOM 兜底） --- */
async function _grabUrlViaPage(tabId,frameId){
  return await new Promise(function(res){
    const _msg={type:"GRAB_VIDEO_URL_REQ"};
    const _cb=function(r){
      if(F.runtime.lastError)return res("");
      res((r&&r.url)||"")
    };
    try{
      if(typeof frameId==="number")F.tabs.sendMessage(tabId,_msg,{frameId:frameId},_cb);
      else F.tabs.sendMessage(tabId,_msg,_cb)
    }catch(_e){res("")}
  })
}

/* --- 统一保底入口：媒体缓存(优先匹配 vid) → 页面 --- */
async function _grabUrlAnywhere(tabId,frameId,vid){
  try{
    if(_mediaCache.length){
      const _arr=_mediaCache.slice().reverse();
      if(vid){
        const _hit=_arr.filter(function(x){return x.url.indexOf(vid)!==-1})[0];
        if(_hit)return _hit.url
      }
      const _best=_arr.slice().sort(function(a,b){return b.url.length-a.url.length})[0];
      if(_best&&_best.url)return _best.url
    }
  }catch(_e){}
  return await _grabUrlViaPage(tabId,frameId)
}

/* --- 伪造 Ki() 的输出结构，供 Bi() 生成文件名 ---
 * Bi() 只用到 bitRateList[0].urlList[0] / .format / .resolutionString 和 vid/creator/description/tagList */
function _mkDetail(vid,u){
  return{vid:vid,creator:"",description:"",tagList:[],
    bitRateList:[{bitRate:0,dataSize:0,width:0,height:0,format:"mp4",resolutionString:"",resolutionNumber:0,urlList:[u]}]}
}

/* --- API 请求需要 Referer/Origin，但它们是禁止头、写在 fetch headers 里会被静默丢弃，
 *     只能用 declarativeNetRequest 改写（需 declarativeNetRequestWithHostAccess 权限
 *     + initiatorDomains 限定为扩展自身发起的请求）。 --- */
var _apiRuleReady=false;
async function _ensureApiRule(){
  if(_apiRuleReady)return;
  try{
    await F.declarativeNetRequest.updateSessionRules({
      removeRuleIds:[900770],
      addRules:[{
        id:900770,
        priority:1,
        action:{type:"modifyHeaders",requestHeaders:[
          {header:"Referer",operation:"set",value:"https://www.douyin.com/"},
          {header:"Origin",operation:"set",value:"https://www.douyin.com"}
        ]},
        condition:{resourceTypes:["xmlhttprequest"],initiatorDomains:[F.runtime.id],urlFilter:"||www.douyin.com"}
      }]
    });
    _apiRuleReady=true
  }catch(_e){}
}
try{_initMediaSniffer()}catch(_e){}
async function _ensureOffscreen(){
  try{
    if(F.offscreen&&await F.offscreen.hasDocument())return true;
    await F.offscreen.createDocument({
      url:"offscreen.html",
      reasons:["BLOBS"],
      justification:"保存视频数据需要创建 blob URL"
    });
    return true
  }catch(_e){return false}
}
async function _dlViaOffscreen(url,filename){
  if(!await _ensureOffscreen())throw new Error("无法创建 offscreen 文档");
  const _RID=900772;
  let _host="";
  try{_host=new URL(url).hostname}catch(_e){}
  const _cond={resourceTypes:["xmlhttprequest"],initiatorDomains:[F.runtime.id]};
  if(_host)_cond.urlFilter="||"+_host;
  try{
    await F.declarativeNetRequest.updateSessionRules({removeRuleIds:[_RID],addRules:[{
      id:_RID,
      priority:2,
      action:{type:"modifyHeaders",requestHeaders:[
        {header:"Referer",operation:"set",value:"https://www.douyin.com/"},
        {header:"Origin",operation:"set",value:"https://www.douyin.com"}
      ]},
      condition:_cond
    }]});
    const r=await F.runtime.sendMessage({type:"OFFSCREEN_DOWNLOAD",url:url,filename:filename});
    if(!r||!r.ok)throw new Error((r&&r.error)||"offscreen 下载失败")
  }finally{
    try{await F.declarativeNetRequest.updateSessionRules({removeRuleIds:[_RID]})}catch(_e2){}
  }
}
async function _dlViaBackgroundFetch(tabId,frameId,url,filename){
  const _RID=900771;
  let _host="";
  try{_host=new URL(url).hostname}catch(_e){}
  const _cond={resourceTypes:["xmlhttprequest"],initiatorDomains:[F.runtime.id]};
  if(_host)_cond.urlFilter="||"+_host;
  try{
    await F.declarativeNetRequest.updateSessionRules({removeRuleIds:[_RID],addRules:[{
      id:_RID,
      priority:1,
      action:{type:"modifyHeaders",requestHeaders:[
        {header:"Referer",operation:"set",value:"https://www.douyin.com/"},
        {header:"Origin",operation:"set",value:"https://www.douyin.com"}
      ]},
      condition:_cond
    }]});
    const resp=await fetch(url);
    if(!resp.ok)throw new Error("HTTP "+resp.status);
    const buf=await resp.arrayBuffer();
    await new Promise(function(res,rej){
      const _msg={type:"SAVE_BUFFER_REQ",data:{buf:buf,filename:filename}};
      const _cb=function(r){
        if(F.runtime.lastError)return rej(new Error(F.runtime.lastError.message));
        if(r&&r.ok)return res();
        rej(new Error((r&&r.error)||"保存失败"))
      };
      if(typeof frameId==="number")F.tabs.sendMessage(tabId,_msg,{frameId:frameId},_cb);
      else F.tabs.sendMessage(tabId,_msg,_cb)
    });
  }finally{
    try{await F.declarativeNetRequest.updateSessionRules({removeRuleIds:[_RID]})}catch(_e2){}
  }
}
async function _dlViaDownloads(url,filename){
  try{
    if(!F.downloads||!F.downloads.download)return false;
    if(/^blob:/i.test(String(url)))return false;
    const id=await F.downloads.download({url:url,filename:filename,conflictAction:"uniquify",saveAs:false});
    return id!==undefined&&id!==null
  }catch(_e){return false}
}
